<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStoreKey;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Infrastructure\Connector\FileStorage\PdoFileStorage;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Connector\Pdo\ThemeAssetPdoConnector;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetReadGateway;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetSlide;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetFilter;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetCursor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeAssetReadRepositoryAdapter implements ThemeAssetReadGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly PdoFileStorage $store,
        private readonly ThemeAssetPdoConnector $conn,
    ) {
    }
    #[Override]
    public function resolve(ThemeAssetRef $ref): ?ThemeAsset
    {
        if ($ref instanceof ThemeAsset) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new ThemeAssetFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
    }
    #[Override]
    public function list(?ThemeAssetFilter $filter = null, ?ThemeAssetCursor $cursor = null): ThemeAssetSlide
    {
        $this->logDebug("List for Theme asset on adapter ");
        $span = $this->startSpan("List for Theme asset on adapter");
        try {
            $values = $this->conn->list($filter, $cursor);
            $last = end($values);
            return new ThemeAssetSlide(function (ThemeAssetFilter $slide, ?ThemeAssetCursor $next) use ($filter) {
                return $this->list($filter, $next);
            }, new ThemeAssetCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieve(ThemeAssetFilter $filter): ?ThemeAsset
    {
        $this->logDebug("Retrieve for Theme asset on adapter ");
        $span = $this->startSpan("Retrieve for Theme asset on adapter");
        try {
            return $this->conn->retrieve($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function exists(ThemeAssetFilter $filter): bool
    {
        $this->logDebug("Exists for Theme asset on adapter ");
        $span = $this->startSpan("Exists for Theme asset on adapter");
        try {
            return $this->conn->exists($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function count(?ThemeAssetFilter $filter = null): int
    {
        $this->logDebug("Count for Theme asset on adapter ");
        $span = $this->startSpan("Count for Theme asset on adapter");
        try {
            return $this->conn->count($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function readContent(string $key): BinaryContent
    {
        $this->logDebug("Load Content childs for Theme asset on adapter ");
        $span = $this->startSpan("Load Content childs for Theme asset on adapter");
        try {
            $binary = $this->store->retrieveFile(new FileStoreKey($key));
            if ($binary) {
                return $binary;
            } else {
                throw new NotFoundException('');
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByCodeAndTheme(string $code, ThemeRef $theme): ?ThemeAsset
    {
        $this->logDebug("Find on by code theme for Theme asset on adapter");
        $span = $this->startSpan("Find on by code theme for Theme asset on adapter");
        try {
            return $this->conn->retrieve(new ThemeAssetFilter(codeAndTheme: ThemeAssetFilter::codeAndThemeFilter(code: $code, theme: $theme)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
